#include "image_export.h"
#include <filesystem>
#include <fstream>
#include <iostream>
#include <zlib.h>
using namespace moon;void check(bool x){if(!x)throw std::runtime_error("image export regression");}
std::vector<Pixel> decode(const StaticImageExport& image){std::vector<unsigned char> bytes;const auto& png=image.png;for(std::size_t i=8;i+12<=png.size();){std::uint32_t n=0;for(int c=0;c<4;++c)n=(n<<8)|png[i+c];if(std::string((const char*)png.data()+i+4,4)=="IDAT")bytes.insert(bytes.end(),png.begin()+i+8,png.begin()+i+8+n);i+=n+12;}std::vector<unsigned char> raw((std::size_t(image.width)*4+1)*image.height);uLongf size=raw.size();check(uncompress(raw.data(),&size,bytes.data(),bytes.size())==Z_OK&&size==raw.size());std::vector<Pixel> out;for(int y=0;y<image.height;++y)for(int x=0;x<image.width;++x){const auto i=std::size_t(y)*(image.width*4+1)+1+x*4;out.push_back(raw[i]|(Pixel(raw[i+1])<<8)|(Pixel(raw[i+2])<<16)|(Pixel(raw[i+3])<<24));}return out;}
int wmain(int argc,wchar_t** argv){try{check(argc==2);auto dir=std::filesystem::path(argv[1]);std::filesystem::create_directories(dir);Document d(3,2);d.beginStroke({1,0},0x80112233);d.commitStroke();d.beginStroke({2,1},0xff445566);d.commitStroke();d.markSaved();auto before=d.pixels();auto out=encodeStaticImagePng(d);check(out.width==3&&out.height==2&&out.png.size()>32&&out.png[0]==137);check(decode(out)==out.pixels&&out.pixels[0]==0&&out.pixels[1]==0x80112233);auto scaled=encodeStaticImagePng(d,{50,false,false});check(scaled.width==2&&scaled.height==1&&scaled.pixels[1]==0x80112233);auto trimmed=encodeStaticImagePng(d,{100,true,false});check(trimmed.width==2&&trimmed.height==2);d.commitSelection({},SelectionMask{1,0,2,2,{1,0,0,1}});auto selected=encodeStaticImagePng(d,{200,false,true});check(selected.width==4&&selected.height==4&&selected.pixels[0]>>24);auto path=dir/L"export.png";writeStaticImagePngAtomic(path,out);check(std::filesystem::file_size(path)==out.png.size());check(d.pixels()==before&&!d.dirty());auto h=d.historySize();auto revision=d.revision();try{writeStaticImagePngAtomic(dir/L"missing"/L"fail.png",out);check(false);}catch(const std::runtime_error&){}check(d.historySize()==h&&d.revision()==revision&&!d.dirty());d.deselectPixels();d.addLayer();d.beginStroke({0,0},0xffabcdef);d.commitStroke();d.setLayerVisible(false);check(encodeStaticImagePng(d).pixels==out.pixels);d.setLayerVisible(true);d.setLayerOpacity(.5);check(encodeStaticImagePng(d).pixels[0]==0x80abcdef);d.addLinkedFrame();check(encodeStaticImagePng(d).pixels[0]==0x80abcdef);std::cout<<"image export checks passed\n";}catch(const std::exception& e){std::cerr<<e.what()<<"\n";return 1;}return 0;}
